package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.RequirePkceVO;

class RequirePkceValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of require pkce of oauth client")
  void test_require_pkce_value_holder_assign_plain_value() {
    Object holder = new Object();
    RequirePkceValueHolder<Object> value = new RequirePkceValueHolder<>(holder);
    Assertions.assertSame(holder, value.requirePkce(true), "Setters must return the holder");
    Assertions.assertTrue(value.getRequirePkceValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getRequirePkce().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of require pkce of oauth client")
  void test_require_pkce_value_holder_assign_value_object() {
    Object holder = new Object();
    RequirePkceValueHolder<Object> value = new RequirePkceValueHolder<>(holder);
    RequirePkceVO vo = RequirePkceVO.from(true);
    Assertions.assertFalse(value.getRequirePkceValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.requirePkce(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRequirePkceValue().orElseThrow());
    Assertions.assertSame(holder, value.requirePkce(Optional.empty()));
    Assertions.assertFalse(value.getRequirePkceValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.requirePkce(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRequirePkceValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of require pkce of oauth client against the original")
  void test_require_pkce_value_holder_read() {
    Object holder = new Object();
    RequirePkceValueHolder<Object> value = new RequirePkceValueHolder<>(holder);
    RequirePkceVO vo = RequirePkceVO.from(true);
    RequirePkceVO other = RequirePkceVO.from(true);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getRequirePkceValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRequirePkce(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRequirePkce(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.requirePkce(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRequirePkce(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRequirePkce(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of require pkce of oauth client")
  void test_require_pkce_value_holder_unset() {
    Object holder = new Object();
    RequirePkceValueHolder<Object> value = new RequirePkceValueHolder<>(holder);
    RequirePkceVO vo = RequirePkceVO.from(true);
    value.requirePkce(vo);
    Assertions.assertSame(holder, value.unsetRequirePkceIfMatches("requirePkce_other"));
    Assertions.assertTrue(value.getRequirePkceValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRequirePkceIfMatches("requirePkce"));
    Assertions.assertFalse(value.getRequirePkceValue().isPresent(),
        "The field name must clear the value");
    value.requirePkce(vo);
    Assertions.assertSame(holder, value.unsetRequirePkce());
    Assertions.assertFalse(value.getRequirePkceValue().isPresent(), "Unset must clear the value");
  }
}
